// ─── real wallet addresses from old system ────────────────────────────────────

const walletUpdates = [
  { id: "seed-pm-1", walletAddress: "bc1q6pfzmdrmm6gw2h63ra7tj7eazhhywktlzkjhpa" },      // BTC
  { id: "seed-pm-2", walletAddress: "0x5D46508e66a594f2EE12762BaBB290BDe33A914e" },        // ETH
  { id: "seed-pm-3", walletAddress: "TX9fM9twSCFFLnF9ipfg6zfBcDj57YXDCc" },               // USDT TRC20
];

// ─── main ─────────────────────────────────────────────────────────────────────

async function main() {
  console.log("Starting old data import...");

  // 1. Update payment method wallet addresses with real addresses from old system
  console.log("Updating payment method wallet addresses...");
  for (const wu of walletUpdates) {
    await db.paymentMethod.update({
      where: { id: wu.id },
      data: { walletAddress: wu.walletAddress },
    }).catch(() => {
      console.log(`  Warning: payment method ${wu.id} not found, skipping`);
    });
  }

  // 2. Add extra instruments not already in new seed
  console.log("Adding additional instruments...");
  for (const inst of newInstruments) {
    await db.instrument.upsert({
      where: { source_target: { source: inst.source, target: inst.target } },
      update: { livePriceEnabled: inst.livePriceEnabled, priceSymbol: inst.priceSymbol, tradingViewSymbol: inst.tradingViewSymbol, bidPrice: inst.bidPrice, askPrice: inst.askPrice },
      create: { source: inst.source, target: inst.target, enabled: true, ...inst },
    });
    console.log(`  ${inst.source}/${inst.target}`);
  }

  // 3. Import copy traders as CopyTrader profile records only (no User accounts)
  console.log(`Importing ${oldTraders.length} copy traders...`);

  for (const t of oldTraders) {
    const firstName = clean(t.firstName) || "Trader";
    const lastName = clean(t.lastName);

    await db.copyTrader.create({
      data: {
        sn: t.sn,
        firstName,
        lastName,
        country: t.country.replace(/_/g, " "),
        avatar: t.dp,
        bio: clean(t.bio) || null,
        cumulativePnl: t.cumulativePnl,
        profitRate7d: t.profitRate7d,
        profitRate30d: t.profitRate30d,
        profitRate90d: t.profitRate90d,
        maxDrawdown: t.maxDrawdown,
        profitShareRatio: t.profitShareRatio,
        accountInstruments: t.accountInstruments,
        copiersCount: t.copiersCount,
        copiersEarnings: t.copiersEarnings,
      },
    });

    process.stdout.write(`  [${t.sn}] ${firstName} ${lastName} (${t.copiersCount.toLocaleString()} copiers)\n`);
  }

  console.log("\nImport complete.");
  console.log(`  Traders imported: ${oldTraders.length}`);
  console.log(`  Extra instruments added: ${newInstruments.length}`);
  console.log(`  Payment methods updated: ${walletUpdates.length}`);
}

main()
  .catch((e) => { console.error(e); process.exit(1); })
  .finally(() => db.$disconnect());
